[System.IO.File]::WriteAllBytes($aux, [Convert]::FromBase64String(($conteudoBase64 -replace '\s', '')))
Write-Host '[INICIO] Retomada dos ensaios, corrigindo aviso findfont.' -ForegroundColor Cyan
# O programa Python filho isola stderr de Matplotlib e registra apenas erros reais.
$ErrorActionPreference = 'Continue'
& $python -u $aux
$codigo = $LASTEXITCODE
if ($codigo -ne 0) { throw "Falha na recuperacao. Codigo $codigo. Consulte o erro acima. OOF e arquivos anteriores preservados." }
Write-Host '[PRONTO] Galerias reunidas no painel e abertura solicitada ao navegador.' -ForegroundColor Green
